  {!map&&!failed&&<p role='status'>Loading the authenticated COS fleet…</p>}
  <details className='cos-fleet-tab-summary' open={view==='map'} key={view}><summary>Fleet totals &amp; quick filters</summary>  <div className='cos-fleet-stats' aria-label='Fleet scope summary'>{[[wholeSourceHeadline?'FIELD EQUIPMENT':recorded.roster?'COMBINED FIELD':'FIELD UNITS',wholeSourceHeadline?mhelpPhysical!.field:headlineCounts.field,'field',fullInventoryHeadline?'mHelpDesk Product IDs · saved source, see timestamp above':recorded.roster?'Linked and unlinked COS representations, not distinct Product IDs':'Current reconciled placement'],...(view==='map'?[['SHOP / ROOT',mhelpPhysical?.shop??'—','shop','All mHelpDesk Shop equipment · excluded from Field outages'],['TOTAL INVENTORY',mhelpPhysical?.total??'—','total','All mHelpDesk Field + Shop Product IDs']]:wholeSourceHeadline?[['SHOP EQUIPMENT',mhelpPhysical!.shop,'shop','mHelpDesk Shop equipment · excluded from customer Field outages']]:[]),['UNITS ONLINE',failed?'—':headlineCounts.online,'online','Field camera units'],['UNITS OFFLINE',failed?'—':headlineCounts.offline,'offline','Field camera units'],['UNITS UNVERIFIED',headlineCounts.unknown,'unknown','Field camera units'],[showMhelpAddressQueue&&mhelpAddresses?'MHELP ADDRESS QUEUE':'MISSING MAP LOCATION',showMhelpAddressQueue&&mhelpAddresses?mhelpAddresses.unlocated:locationsReady?missingLocations:'…','verify',showMhelpAddressQueue&&mhelpAddresses?'Field Product IDs awaiting address coordinates':'Combined COS records without an installation point']].map(([label,count,quick,note])=><button key={label} className={'cos-fleet-stat cos-fleet-stat-'+quick} onClick={()=>{if(quick==='verify'){if(showMhelpAddressQueue&&mhelpAddresses){setView('map');requestAnimationFrame(()=>{const queue=document.querySelector<HTMLDetailsElement>('.cos-mhelp-address-followups');if(queue){queue.open=true;queue.scrollIntoView({block:'start'});}});}else{setLocationQueue('missing');tab('verify');}}else if(quick==='shop'){setView('fleet');setFilters(f=>({...f,placement:'shop',status:'all'}));}else if(quick==='total'){setView('fleet');setFilters({...initialFleetFilters,placement:'all'});}else{setView('map');setFilters(f=>({...f,layer:'camera',placement:quick==='field'?'field':f.placement,status:quick==='field'?'all':String(quick)}));}}}>{(quick==='online'||quick==='offline'||quick==='unknown'?<i className={'cos-board-status-dot cos-board-dot-'+quick} aria-hidden='true'/>:<FleetCardIcon kind={quick==='shop'?'shop':quick==='total'?'inventory':quick==='verify'?'location':'camera'}/>)}<span>{label}</span><strong>{map&&!(recorded.error&&(quick==='field'||quick==='verify'))?count:'—'}</strong><small className='cos-fleet-stat-explanation'>{note}</small></button>)}</div></details>
  {effectiveUpload?.cosManualShopCount>0&&<p className='cos-fleet-camera-total'>{effectiveUpload.cosManualShopCount} confirmed COS Shop move(s) applied to the accepted mHelp inventory.</p>}
