  {view==='map'&&<><div className='cos-fleet-workspace'><section className='cos-fleet-unit-panel' aria-label='Fleet units in view'><div><h2>{recorded.roster?'Equipment entries':'Units in view'} <b>{filtered.length+filteredSource.length}</b></h2><small>{recorded.roster?'Device and source entries · may include tracker-only records':'UNIT / SITE · CAM / RTR / BAT'}</small></div>{filtersPanel}<div className='cos-fleet-unit-list' aria-busy={editorBusy||loading}>{filtered.slice(0,limit).map(row=><button key={row.id} data-unit-id={row.id} disabled={editorBusy} className={'cos-fleet-unit-row'+(selected===row.id?' selected':'')} onClick={()=>open(row.id)}><span className='cos-fleet-unit-copy'><strong><i className={'cos-fleet-row-dot cos-signal-'+row.cameraState} aria-hidden='true'>●</i>{row.displayName||row.name}</strong><small>{row.displayCustomer||row.unit.site||row.unit.customer||'Site not supplied'}</small><small>{row.displayAddress?.label||'Installation address'}: {(row.displayAddress?.text??row.unit.address)||'Not supplied'}</small><small className='cos-fleet-card-location'>{row.placement==='shop'?(shopOnly(row)?'SHOP':'SHOP / ROOT'):row.placement.toUpperCase()} · {row.locationVerified?'Verified location':locationTag(row.unit)}</small><FleetBatterySummary row={row} now={cameras.now} compact/>{!shopOnly(row)&&<><small className='cos-fleet-card-evidence'>{unitHealthLabel(row.camera)}</small><LastKnownCameraStatus observation={lastKnown(row)} now={cameras.now}/></>}</span><Signals row={row}/></button>)}{filteredSource.length>0&&<section className='cos-fleet-source-group' aria-label='Unlinked equipment in view'><h3>Unlinked equipment <b>{filteredSource.length}</b></h3><p>Recorded assignments without a verified COS health link. Accepted address estimates are labeled separately from health and verified installation locations.</p>{filteredSource.slice(0,limit).map(record=><FleetSourceEquipment key={record.id} record={record} now={cameras.now} estimate={sourcePins.get(record.id)?.estimate} onSelect={sourcePins.has(record.id)?()=>openSource(record.id):undefined}/>)}</section>}{!filtered.length&&!filteredSource.length&&<p className='field-map-empty'>{!map&&!failed?'Loading saved inventory…':'No units match. Change the filters or open the review queue.'}</p>}{Math.max(filtered.length,filteredSource.length)>limit&&<button onClick={()=>setLimit(v=>v+80)}>Show more equipment ({Math.max(0,filtered.length-limit)+Math.max(0,filteredSource.length-limit)})</button>}</div></section><FleetDashboardMap rows={filtered} locationsReady={locationsReady} pins={acceptedPins.filter(pin=>pin.kind==='source_equipment_estimate'?filteredSource.some(record=>record.id===pin.record.id):filtered.some(row=>row.id===pin.row.id))} layer={filters.layer} onSelect={id=>sourcePins.has(id)?openSource(id):open(id)} selectedId={selectedSourceId||selected} pickLocation={locationPicker?finishPick:null} mhelpAddressUnits={addressDisplayIds} mhelpAddressHealth={addressHealth} mhelpAddressPins={showMhelpAddresses?mhelpAddresses?.pins:undefined} mhelpAddressReviews={showMhelpAddresses?mhelpAddresses?.reviews:undefined} onSelectMhelpAddress={openMhelpAddress} filters={filters}/></div><div className='cos-fleet-map-footnote'><button onClick={()=>{setLocationQueue('missing');tab('verify');}}>{mhelpAddresses?'COS installation verification: ':'Missing map location: '}{recorded.error?'—':locationsReady?missingLocations:'…'}</button><button onClick={()=>{setLocationQueue('estimated');tab('verify');}}>Estimated / source-recorded location: {locationsReady?estimatedLocations:'…'}</button><span>Shop / ROOT and retired units stay off the field map. Estimates require installation verification.</span></div></>}
